package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_3 : Boolean;
    attribute ledState : Boolean := false;
    attribute pwmValue : Integer := 0;
    attribute buzzerHz : Integer := 0;
    attribute prevPressed : Boolean := false;
    perform action tick {
      first start;
      then if io_3 and not prevPressed {
        first start;
        then assign prevPressed := true;
      } else {
        first start;
        then assign prevPressed := false;
      }
      then if not (io_3 and not prevPressed) {
        first start;
        then done;
      }
    }
    out attribute io_0 : Boolean = ledState;
    out attribute io_1 : Real = pwmValue * 1.0;
    out attribute io_2 : Integer = buzzerHz;
    out attribute serial_0_trigger : Boolean = io_3 and not prevPressed;
    out attribute serial_0_value_0 : Boolean = ledState;
    out attribute serial_0_value_1 : Integer = pwmValue;
    out attribute serial_0_value_2 : Integer = buzzerHz;
  }
  part system : Controller;
}
